def _se_desactivo(registro):
    """True si el registro de auditoría corresponde a pasar el producto a inactivo."""
    cambio = (registro.cambios or {}).get('estado') or {}
    if cambio.get('despues') == 'Inactivo':
        return True
    antes = (registro.datos_anteriores or {}).get('estado')
    despues = (registro.datos_nuevos or {}).get('estado')
    return despues == 'inactivo' and antes != 'inactivo'


