        registros = Auditoria.objects.filter(modelo='Producto', objeto_id=str(producto.pk)).order_by('-fecha_hora')
        fecha = next((r.fecha_hora for r in registros if _se_desactivo(r)), ahora)
        Productos.objects.filter(pk=producto.pk).update(fecha_inactivacion=fecha)


